195:     } else if (!strcasecmp(u,"k")) {
196:         mul = 1000;
197:     } else if (!strcasecmp(u,"kb")) {
198:         mul = 1024;
199:     } else if (!strcasecmp(u,"m")) {
200:         mul = 1000*1000;
201:     } else if (!strcasecmp(u,"mb")) {
